package com.eventos.api.controller;
import com.eventos.api.dto.EventDtos.*; import com.eventos.api.service.EventService; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import javax.validation.Valid; import java.util.*;
@RestController @RequestMapping("/api/events") public class EventController { private final EventService service; public EventController(EventService service){this.service=service;} private Long admin(Authentication a){return (Long)a.getPrincipal();}@GetMapping public List<View> list(Authentication a){return service.list(admin(a));}@PostMapping @ResponseStatus(HttpStatus.CREATED) public View create(Authentication a,@Valid @RequestBody Create b){return service.create(admin(a),b);}@PatchMapping("/{eventId}") public View update(Authentication a,@PathVariable Long eventId,@Valid @RequestBody Update b){return service.update(admin(a),eventId,b);}@DeleteMapping("/{eventId}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable Long eventId){service.delete(admin(a),eventId);} }
